def read_history(filepath: Path) -> list[TransitionRecord]:
    if not filepath.is_file():
        return []
    text = filepath.read_text(encoding="utf-8")
    matches = list(_HISTORY_HEADING_RE.finditer(text))
    if not matches:
        return []
    records: list[TransitionRecord] = []
    for i, m in enumerate(matches):
        ts = m.group(1)
        start = m.end()
        end = matches[i + 1].start() if i + 1 < len(matches) else len(text)
        block = text[start:end]
        records.append(_parse_history_block(ts, block))
    return records


def _format_history_block(record: TransitionRecord) -> str:
    return (
        f"## {record.timestamp}\n\n"
        f"- previous_state: {record.previous_state}\n"
        f"- next_state: {record.next_state}\n"
        f"- commit: {record.commit}\n"
        f"- thread_name: {record.thread_name}\n"
        f"- notes: {record.notes}\n"
        "\n"
    )


def append_history(filepath: Path, record: TransitionRecord) -> None:
    block = _format_history_block(record)
    filepath.parent.mkdir(parents=True, exist_ok=True)
    if filepath.is_file():
        existing = filepath.read_text(encoding="utf-8")
        if existing and not existing.endswith("\n"):
            existing += "\n"
        filepath.write_text(existing + block, encoding="utf-8")
    else:
        filepath.write_text("# State Transition History\n\n" + block, encoding="utf-8")


def has_human_intervention_request(quest_dir: Path) -> bool:
    return (quest_dir / "human_intervention_request.md").is_file()

"""Machine definitions and loader for the canonical recursive quest runner."""

from __future__ import annotations

from pathlib import Path

from .machine import ConcreteStateMachine
from .protocols import StateMachineDefinition
from .quest_v2_nodes import (
    CompletedGateNode,
    ExecuteActiveSliceNode,
    PhysicalPlanningNode,
    PrepareNextSliceNode,
    PrePlanningGateNode,
    QuestDocumentingNode,
    ReviewPhysicalPlanNode,
    SliceCompletedNode,
    SliceImplementingNode,
    SlicePolishingFixNode,
    SlicePolishingReviewNode,
    SliceSetupNode,
)


def build_quest_machine_definition() -> StateMachineDefinition:
    return StateMachineDefinition(
        machine_name="quest",
        node_map={
            "PrePlanning": PrePlanningGateNode,
            "PhysicalPlanning": PhysicalPlanningNode,
            "ReviewPhysicalPlan": ReviewPhysicalPlanNode,
            "PrepareNextSlice": PrepareNextSliceNode,
            "ExecuteSlice": ExecuteActiveSliceNode,
            "QuestDocumenting": QuestDocumentingNode,
            "Completed": CompletedGateNode,
        },
        terminal_states=("Completed",),
    )


def build_slice_machine_definition() -> StateMachineDefinition:
    return StateMachineDefinition(
        machine_name="slice",
        node_map={
            "SliceSetup": SliceSetupNode,
            "Implementing": SliceImplementingNode,
            "PolishingReview": SlicePolishingReviewNode,
            "PolishingFix": SlicePolishingFixNode,
            "Completed": SliceCompletedNode,
        },
        terminal_states=("Completed",),
    )


class QuestV2MachineLoader:
    def __init__(self, io: object) -> None:
        self.io = io
        self._quest_def = build_quest_machine_definition()
        self._slice_def = build_slice_machine_definition()

    def LoadStateMachine(self, state_machine_dir: Path) -> ConcreteStateMachine:
        p = state_machine_dir.resolve()
        qd = self.io.quest_dir.resolve()
        if p == qd:
            return ConcreteStateMachine(p, self._quest_def, self.io)
        return ConcreteStateMachine(p, self._slice_def, self.io)

    def LoadTopStateMachine(self, machine_root_dir: Path) -> ConcreteStateMachine:
        return self.LoadStateMachine(machine_root_dir)

"""Quest Runner command-line interface wrapping the REST service."""

from __future__ import annotations

import argparse
import json
import os
import sys
import textwrap
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable, TextIO
from urllib.error import HTTPError, URLError
from urllib.parse import urlencode, urljoin
from urllib.request import Request, urlopen

_DEFAULT_BASE_URL = "http://localhost:9002"
_SERVICE_NAME = "quest-runner"
_VALID_QUEST_TYPES = frozenset({"main", "side"})
_VALID_SCOPES = frozenset({"physicalplan", "polishing"})
_VALID_STATUSES = frozenset({"open", "completed", "all"})
_VALID_ISSUE_STATUSES = frozenset({"open", "completed"})
_VALID_OUTCOMES = frozenset({"Fixed", "NotFixed"})


class CliValidationError(Exception):
    pass


class TransportError(Exception):
    def __init__(
        self,
        message: str,
        *,
        base_url: str | None = None,
        endpoint: str | None = None,
    ) -> None:
        super().__init__(message)
        self.base_url = base_url
        self.endpoint = endpoint


@dataclass(frozen=True)
class RecordedRequest:
    method: str
    url: str
    body: dict[str, Any] | None


RequestFn = Callable[[str, str, dict[str, Any] | None], tuple[int, dict[str, Any]]]


def _script_start_path(argv: list[str] | None) -> Path:
    if argv is None:
        return Path(sys.argv[0]).resolve()
    if not argv:
        return Path.cwd()
    return Path(argv[0]).resolve()


def _find_repo_root(start: Path) -> Path | None:
    current = start.resolve()
    if current.is_file():
        current = current.parent
    for directory in (current, *current.parents):
        if (directory / "config" / "services.json").is_file():
            return directory
    return None


def _normalize_host(host: str) -> str:
    if host.strip() == "0.0.0.0":
        return "localhost"
    return host.strip()


def _service_url_from_config(repo_root: Path) -> str | None:
    config_path = repo_root / "config" / "services.json"
    try:
        raw = json.loads(config_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(raw, list):
        return None
    for entry in raw:
        if not isinstance(entry, dict):
            continue
        if entry.get("name") != _SERVICE_NAME:
            continue
        host = entry.get("host")
        port = entry.get("port")
        if not host or port is None:
            return None
        return f"http://{_normalize_host(str(host))}:{port}"
    return None


def resolve_base_url(
    *,
    cli_base_url: str | None = None,
    env: dict[str, str] | None = None,
    start_path: Path | None = None,
) -> tuple[str, str | None]:
    """Return (base_url, warning_message). warning is None when no fallback was used."""
    if cli_base_url:
        return cli_base_url.rstrip("/"), None

    environment = os.environ if env is None else env
    env_url = environment.get("QUEST_RUNNER_URL", "").strip()
    if env_url:
        return env_url.rstrip("/"), None

    anchor = start_path if start_path is not None else Path.cwd()
    repo_root = _find_repo_root(anchor)
    if repo_root is not None:
        from_config = _service_url_from_config(repo_root)
        if from_config:
            return from_config.rstrip("/"), None

    return _DEFAULT_BASE_URL, (
        f"Could not resolve quest-runner service URL from config/services.json; "
        f"using fallback {_DEFAULT_BASE_URL}"
    )


def default_request(method: str, url: str, body: dict[str, Any] | None) -> tuple[int, dict[str, Any]]:
    headers = {
        "Accept": "application/json",
        "Content-Type": "application/json",
    }
    payload = None
    if body is not None:
        payload = json.dumps(body).encode("utf-8")
    request = Request(url, data=payload, method=method, headers=headers)
    try:
        with urlopen(request) as response:
            text = response.read().decode("utf-8")
            status = response.status
    except HTTPError as exc:
        text = exc.read().decode("utf-8")
        status = exc.code
    except URLError as exc:
        raise TransportError(str(exc.reason)) from exc

    if not text.strip():
        return status, {}
    try:
        parsed = json.loads(text)
    except json.JSONDecodeError:
        parsed = {"error": text}
    if not isinstance(parsed, dict):
        return status, {"data": parsed}
    return status, parsed


def _endpoint_path(path: str) -> str:
    return path if path.startswith("/") else f"/{path}"


def _join_url(base_url: str, path: str, query: dict[str, Any] | None = None) -> str:
    url = urljoin(f"{base_url.rstrip('/')}/", _endpoint_path(path).lstrip("/"))
    if query:
        filtered = {key: value for key, value in query.items() if value is not None}
        if filtered:
            url = f"{url}?{urlencode(filtered, doseq=True)}"
    return url


def _send_request(
    request_fn: RequestFn,
    method: str,
    *,
    base_url: str,
    endpoint: str,
    body: dict[str, Any] | None,
    query: dict[str, Any] | None = None,
) -> tuple[int, dict[str, Any]]:
    try:
        return request_fn(method, _join_url(base_url, endpoint, query), body)
    except TransportError as exc:
        if exc.base_url is not None and exc.endpoint is not None:
            raise
        raise TransportError(str(exc), base_url=base_url, endpoint=endpoint) from exc


