def parse_step_commit_message(message: str) -> ParsedCommitMessage | None:
    """Return structured metadata, or ``None`` if the message is not parseable."""
    text = message.strip()
    if not text:
        return None
    lines = text.splitlines()
    headers: dict[str, str] = {}
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if not line:
            i += 1
            break
        if ":" not in line:
            return None
        key, _, rest = line.partition(":")
        key = key.strip()
        val = rest.strip()
        if key in headers:
            return None
        headers[key] = val
        i += 1

